SELECT bb.*, u.username as user_name, u.uid, u.avatar, bi.book_name, bi.author, bi.cover_url, bi.category_id, bc.category_code, bc.category_name, au.username as admin_name FROM book_borrow bb LEFT JOIN sys_user u ON bb.user_id = u.user_id LEFT JOIN book_info bi ON bb.book_id = bi.book_id LEFT JOIN book_category bc ON bi.category_id = bc.category_id LEFT JOIN sys_user au ON bb.confirm_admin_id = au.user_id WHERE bb.borrow_id IN
#{id}
ORDER BY bb.borrow_id
